use crate::{capability::{Capability,CapabilityError,CapabilityPolicy,CapabilityRegistry},compiler::{FunctionInfo,Opcode},parser::Expr,verifier::{self,VerificationError}};
use std::collections::HashMap;
#[derive(Debug,Clone,PartialEq)]pub enum RuntimeError{StackUnderflow,InvalidConstant(usize),UndefinedVariable(String),UndefinedFunction(String),ArityMismatch{function:String,expected:usize,got:usize},TypeError(&'static str),DivisionByZero,InvalidJump(usize),CallStackOverflow,CapabilityDenied(Capability),CapabilityLimitExceeded(Capability),BytecodeVerification(VerificationError)}
#[derive(Debug,Clone)]struct Frame{return_ip:usize,locals:HashMap<String,Expr>}
pub struct VM{stack:Vec<Expr>,constants:Vec<Expr>,code:Vec<Opcode>,ip:usize,globals:HashMap<String,Expr>,frames:Vec<Frame>,functions:HashMap<String,FunctionInfo>,loops:Vec<(usize,i64)>,max_call_depth:usize,capabilities:CapabilityRegistry}
impl VM{pub fn new(c:Vec<Expr>,code:Vec<Opcode>)->Self{Self::with_capabilities(c,code,HashMap::new(),CapabilityPolicy::deny_all())}pub fn with_functions(c:Vec<Expr>,code:Vec<Opcode>,functions:HashMap<String,FunctionInfo>)->Self{Self::with_capabilities(c,code,functions,CapabilityPolicy::deny_all())}pub fn with_capabilities(c:Vec<Expr>,code:Vec<Opcode>,functions:HashMap<String,FunctionInfo>,policy:CapabilityPolicy)->Self{Self{stack:Vec::new(),constants:c,code,ip:0,globals:HashMap::new(),frames:Vec::new(),functions,loops:Vec::new(),max_call_depth:1024,capabilities:CapabilityRegistry::new(policy)}}pub fn run(&mut self)->Result<(),RuntimeError>{verifier::verify(&self.constants,&self.code,&self.functions).map_err(RuntimeError::BytecodeVerification)?;while self.ip<self.code.len(){let op=self.code[self.ip].clone();match op{Opcode::LoadConst(i)=>self.stack.push(self.constants.get(i).cloned().ok_or(RuntimeError::InvalidConstant(i))?),Opcode::LoadVar(n)=>self.stack.push(self.load_var(&n)?),Opcode::StoreVar(n)=>{let v=self.pop()?;self.store_var(n,v)},Opcode::Add|Opcode::Sub|Opcode::Mul|Opcode::Div=>self.binary_numeric(op)?,Opcode::Equal|Opcode::NotEqual|Opcode::Greater|Opcode::Less|Opcode::GreaterEqual|Opcode::LessEqual=>self.compare(op)?,Opcode::Print=>println!("{:?}",self.pop()?),Opcode::JumpIfFalse(t)=>{if !Self::truthy(&self.pop()?){self.jump(t)?;continue}},Opcode::Jump(t)=>{self.jump(t)?;continue},Opcode::RepeatStart=>{let n=match self.pop()?{Expr::Number(n)if n>=0=>n,_=>return Err(RuntimeError::TypeError("repeat expects a non-negative integer"))};self.loops.push((self.ip,n))},Opcode::RepeatEnd(start)=>{if let Some((_,n))=self.loops.pop(){if n>1{self.loops.push((start,n-1));self.jump(start+1)?;continue}}},Opcode::Call(n,a)=>self.call(&n,a)?,Opcode::Return=>{if self.frames.is_empty(){break}let result=self.pop().unwrap_or(Expr::Null);let f=self.frames.pop().unwrap();self.ip=f.return_ip;self.stack.push(result);continue},Opcode::NetworkScan=>{self.authorize(Capability::NetworkScan)?;let _=self.pop()?;self.stack.push(Expr::String("network.scan host capability granted; host adapter required".into()))},Opcode::Halt=>break}self.ip+=1}Ok(())}fn authorize(&mut self,c:Capability)->Result<(),RuntimeError>{match self.capabilities.request(c.clone()){Ok(())=>Ok(()),Err(CapabilityError::Denied(_))=>Err(RuntimeError::CapabilityDenied(c)),Err(CapabilityError::LimitExceeded(_))=>Err(RuntimeError::CapabilityLimitExceeded(c))}}fn call(&mut self,name:&str,argc:usize)->Result<(),RuntimeError>{let info=self.functions.get(name).cloned().ok_or_else(||RuntimeError::UndefinedFunction(name.into()))?;if argc!=info.params.len(){return Err(RuntimeError::ArityMismatch{function:name.into(),expected:info.params.len(),got:argc})}if self.frames.len()>=self.max_call_depth{return Err(RuntimeError::CallStackOverflow)}let mut locals=HashMap::new();for p in info.params.iter().rev(){locals.insert(p.clone(),self.pop()?);}self.frames.push(Frame{return_ip:self.ip+1,locals});self.ip=info.entry;Ok(())}fn load_var(&self,n:&str)->Result<Expr,RuntimeError>{if let Some(f)=self.frames.last(){if let Some(v)=f.locals.get(n){return Ok(v.clone())}}self.globals.get(n).cloned().ok_or_else(||RuntimeError::UndefinedVariable(n.into()))}fn store_var(&mut self,n:String,v:Expr){if let Some(f)=self.frames.last_mut(){f.locals.insert(n,v)}else{self.globals.insert(n,v)}}fn pop(&mut self)->Result<Expr,RuntimeError>{self.stack.pop().ok_or(RuntimeError::StackUnderflow)}fn binary_numeric(&mut self,op:Opcode)->Result<(),RuntimeError>{let r=self.pop()?;let l=self.pop()?;let v=match(l,r){(Expr::Number(a),Expr::Number(b))=>{if matches!(op,Opcode::Div)&&b==0{return Err(RuntimeError::DivisionByZero)}match op{Opcode::Add=>Expr::Number(a+b),Opcode::Sub=>Expr::Number(a-b),Opcode::Mul=>Expr::Number(a*b),Opcode::Div=>Expr::Number(a/b),_=>unreachable!()}},(Expr::Float(a),Expr::Float(b))=>{if matches!(op,Opcode::Div)&&b==0.0{return Err(RuntimeError::DivisionByZero)}Expr::Float(match op{Opcode::Add=>a+b,Opcode::Sub=>a-b,Opcode::Mul=>a*b,Opcode::Div=>a/b,_=>unreachable!()})},(Expr::Number(a),Expr::Float(b))=>{let a=a as f64;if matches!(op,Opcode::Div)&&b==0.0{return Err(RuntimeError::DivisionByZero)}Expr::Float(match op{Opcode::Add=>a+b,Opcode::Sub=>a-b,Opcode::Mul=>a*b,Opcode::Div=>a/b,_=>unreachable!()})},(Expr::Float(a),Expr::Number(b))=>{let b=b as f64;if matches!(op,Opcode::Div)&&b==0.0{return Err(RuntimeError::DivisionByZero)}Expr::Float(match op{Opcode::Add=>a+b,Opcode::Sub=>a-b,Opcode::Mul=>a*b,Opcode::Div=>a/b,_=>unreachable!()})},_=>return Err(RuntimeError::TypeError("arithmetic expects numeric values"))};self.stack.push(v);Ok(())}fn compare(&mut self,op:Opcode)->Result<(),RuntimeError>{let r=self.pop()?;let l=self.pop()?;let v=match(&l,&r,op){(Expr::Number(a),Expr::Number(b),Opcode::Equal)=>a==b,(Expr::Number(a),Expr::Number(b),Opcode::NotEqual)=>a!=b,(Expr::Number(a),Expr::Number(b),Opcode::Greater)=>a>b,(Expr::Number(a),Expr::Number(b),Opcode::Less)=>a<b,(Expr::Number(a),Expr::Number(b),Opcode::GreaterEqual)=>a>=b,(Expr::Number(a),Expr::Number(b),Opcode::LessEqual)=>a<=b,(Expr::Float(a),Expr::Float(b),Opcode::Equal)=>a==b,(Expr::Float(a),Expr::Float(b),Opcode::NotEqual)=>a!=b,(Expr::Float(a),Expr::Float(b),Opcode::Greater)=>a>b,(Expr::Float(a),Expr::Float(b),Opcode::Less)=>a<b,(Expr::Float(a),Expr::Float(b),Opcode::GreaterEqual)=>a>=b,(Expr::Float(a),Expr::Float(b),Opcode::LessEqual)=>a<=b,(Expr::String(a),Expr::String(b),Opcode::Equal)=>a==b,(Expr::String(a),Expr::String(b),Opcode::NotEqual)=>a!=b,(Expr::Bool(a),Expr::Bool(b),Opcode::Equal)=>a==b,(Expr::Bool(a),Expr::Bool(b),Opcode::NotEqual)=>a!=b,(Expr::Null,Expr::Null,Opcode::Equal)=>true,(Expr::Null,Expr::Null,Opcode::NotEqual)=>false,_=>return Err(RuntimeError::TypeError("comparison requires compatible values"))};self.stack.push(Expr::Bool(v));Ok(())}fn truthy(v:&Expr)->bool{match v{Expr::Number(n)=>*n!=0,Expr::Float(n)=>*n!=0.0,Expr::String(s)=>!s.is_empty(),Expr::Bool(b)=>*b,Expr::Null=>false,_=>true}}fn jump(&mut self,t:usize)->Result<(),RuntimeError>{if t>=self.code.len(){return Err(RuntimeError::InvalidJump(t))}self.ip=t;Ok(())}}
